package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.util.ElapsedTime;
import com.qualcomm.robotcore.util.Range;

import org.firstinspires.ftc.teamcode.config.Tuned;

import java.util.ArrayDeque;

// Generated by refract-suite ftc-construct. One touch of a turret end stop, used by the Yaw Tuner (to measure the
// stops) and by YawHoming (to find the zero). Works in the turret's own angle (Yaw.frontDeg()), which only has to be
// consistent for the length of a touch, not true.
//   fast hit   drive at the stop at a given speed until the encoder stops (a stall)           -> roughDeg
//   back off   a few degrees away from it
//   creep      drive back in slowly until it stalls again                                    -> preciseDeg
// The slow last touch is the accurate one: it is always the same speed and push, so the angle is the same every time.
public final class StopTouch {
    public enum Phase { APPROACH, BACKOFF, CREEP, DONE, FAILED }

    // test procedure settings, not robot measurements
    public static final double CREEP_DEG_S = 20, BACKOFF_DEG = 3, BACKOFF_RATE_DEG_S = 60;
    private static final double STALL_WINDOW_S = 0.08;
    private static final double ARM_MOVED_DEG = 1.5, CREEP_ARM_MOVED_DEG = 1.0, NO_MOVE_S = 0.6, BACKOFF_NO_MOVE_S = 0.5;
    private static final double BACKOFF_TOLERANCE_DEG = 0.8, BACKOFF_TIMEOUT_S = 0.9, CREEP_NO_MOVE_S = 1.0;
    private static final double SOFT_LAND_DEG = 25;
    // the crossing never goes faster than this many deg/s for each degree left to the expected stop (less 2 deg), so a
    // late loop cannot carry the turret into the stop at the crossing speed
    private static final double CROSS_SLOW_PER_S = 8;

    private final Yaw yaw;
    private final int dir;
    private final double fastRate, creepRate, maxTravelDeg, expectedStopDeg;
    private final ElapsedTime phaseTimer = new ElapsedTime();
    private final ArrayDeque<double[]> window = new ArrayDeque<>();
    private Phase phase;
    private double phaseStartDeg, startDeg, roughDeg = Double.NaN, preciseDeg = Double.NaN, backoffDeg = BACKOFF_DEG;
    private String why = "";

    // fast hit at fastRate (deg/s) toward the stop in direction dir (+1 left, -1 right), then back off and creep.
    // expectedStopDeg: where the stop should be if the angle is already right (NaN if not known): the last
    // SOFT_LAND_DEG before it are driven at twice the creep speed. maxTravelDeg: give up after this far without a stall.
    public static StopTouch fastThenCreep(Yaw yaw, int dir, double fastRate, double creepRate, double expectedStopDeg, double maxTravelDeg) {
        return new StopTouch(yaw, dir, fastRate, creepRate, expectedStopDeg, maxTravelDeg, Phase.APPROACH, Double.NaN, BACKOFF_DEG);
    }

    // already near the stop (a few degrees to dozens inside): just creep in
    public static StopTouch creepFromInside(Yaw yaw, int dir, double creepRate, double maxTravelDeg) {
        return new StopTouch(yaw, dir, 0, creepRate, Double.NaN, maxTravelDeg, Phase.CREEP, Double.NaN, BACKOFF_DEG);
    }

    // the turret rests at a stop it just touched (stallDeg): back off backoffDeg, then creep in again
    public static StopTouch backoffThenCreep(Yaw yaw, int dir, double stallDeg, double backoffDeg, double creepRate, double maxTravelDeg) {
        return new StopTouch(yaw, dir, 0, creepRate, Double.NaN, maxTravelDeg, Phase.BACKOFF, stallDeg, backoffDeg);
    }

    private StopTouch(Yaw yaw, int dir, double fastRate, double creepRate, double expectedStopDeg, double maxTravelDeg,
                      Phase first, double stallDeg, double backoffDeg) {
        this.yaw = yaw;
        this.dir = dir;
        this.fastRate = fastRate;
        this.creepRate = creepRate;
        this.expectedStopDeg = expectedStopDeg;
        this.maxTravelDeg = maxTravelDeg;
        this.backoffDeg = backoffDeg;
        this.roughDeg = stallDeg;
        startDeg = yaw.frontDeg();
        enter(first);
    }

    public boolean finished() {
        return phase == Phase.DONE || phase == Phase.FAILED;
    }

    public boolean failed() {
        return phase == Phase.FAILED;
    }

    public String why() {
        return why;
    }

    public Phase phase() {
        return phase;
    }

    // angle of the fast hit (NaN if there was none) and of the slow last touch
    public double roughDeg() {
        return roughDeg;
    }

    public double preciseDeg() {
        return preciseDeg;
    }

    // every loop until finished()
    public void update() {
        if (finished()) return;
        double now = System.nanoTime() / 1e9;
        double deg = yaw.frontDeg();
        window.addLast(new double[]{now, deg});
        while (window.size() > 2 && now - window.peekFirst()[0] > STALL_WINDOW_S * 1.5) window.pollFirst();
        double moved = Math.abs(deg - phaseStartDeg);
        switch (phase) {
            case APPROACH: {
                if (Math.abs(deg - startDeg) > maxTravelDeg) {
                    fail("no stop found in the whole travel");
                    return;
                }
                double rate = dir * fastRate;
                if (!Double.isNaN(expectedStopDeg) && dir * (expectedStopDeg - deg) < SOFT_LAND_DEG) {
                    rate = dir * Math.min(fastRate, 2 * creepRate);
                }
                driveRate(yaw, rate);
                // a stall counts once it has moved (or sat 0.6 s: it may start at the stop)
                if ((moved >= ARM_MOVED_DEG || phaseTimer.seconds() >= NO_MOVE_S) && stalled(now)) {
                    roughDeg = windowAverage();
                    yaw.setRawPower(0);
                    enter(Phase.BACKOFF);
                }
                break;
            }
            case BACKOFF: {
                double target = roughDeg - dir * backoffDeg;
                double err = target - deg;
                if (Math.abs(err) <= BACKOFF_TOLERANCE_DEG) {
                    yaw.setRawPower(0);
                    enter(Phase.CREEP);
                    break;
                }
                if (phaseTimer.seconds() >= BACKOFF_NO_MOVE_S && Math.abs(deg - phaseStartDeg) < 0.5) {
                    fail("the turret did not move off the stop: check for binding");
                    return;
                }
                if (phaseTimer.seconds() > BACKOFF_TIMEOUT_S) {
                    fail("could not back off the stop");
                    return;
                }
                driveRate(yaw, rateToward(err, BACKOFF_RATE_DEG_S));
                break;
            }
            case CREEP: {
                if (Math.abs(deg - startDeg) > maxTravelDeg) {
                    fail("no stop found in the whole travel");
                    return;
                }
                driveRate(yaw, dir * creepRate);
                if (moved < CREEP_ARM_MOVED_DEG) {
                    if (phaseTimer.seconds() >= CREEP_NO_MOVE_S) fail("the turret did not creep: check for binding");
                    break;
                }
                if (stalled(now)) {
                    preciseDeg = windowAverage();
                    yaw.setRawPower(0);
                    phase = Phase.DONE;
                }
                break;
            }
            default:
                break;
        }
    }

    // ---------- shared by the tuner and the homing ----------

    // power that moves the turret at about rateDegS (+ = toward larger angles): the tuned friction and speed per
    // power, scaled to the battery like Yaw.track does
    public static void driveRate(Yaw yaw, double rateDegS) {
        if (rateDegS == 0) {
            yaw.setRawPower(0);
            return;
        }
        double power = (Math.signum(rateDegS) * Tuned.yawKs + Tuned.yawKv * rateDegS) * Tuned.yawTuningVoltage / yaw.voltage();
        yaw.setRawPower(Range.clip(Tuned.yawPowerSign * power, -1, 1));
    }

    // crossing rate toward the angle targetDeg that lies stopShortDeg inside a stop at expectedStopDeg, moving in
    // direction dir: the tuned kP up to capDegS, and slower the closer the expected stop is
    public static double crossRate(double deg, double targetDeg, double expectedStopDeg, int dir, double capDegS) {
        double left = dir * (expectedStopDeg - deg);
        double cap = Math.min(capDegS, Math.max(CREEP_DEG_S, CROSS_SLOW_PER_S * (left - 2)));
        return rateToward(targetDeg - deg, cap);
    }

    // turn rate toward a target angle error: the tuned kP, never faster than capDegS
    public static double rateToward(double errDeg, double capDegS) {
        return Range.clip(Tuned.yawKp * errDeg, -capDegS, capDegS);
    }

    // ---------- inside ----------

    private void enter(Phase next) {
        phase = next;
        phaseTimer.reset();
        phaseStartDeg = yaw.frontDeg();
        window.clear();
    }

    private void fail(String reason) {
        yaw.setRawPower(0);
        why = reason;
        phase = Phase.FAILED;
    }

    // the encoder moved no more than a few ticks over the last STALL_WINDOW_S
    private boolean stalled(double now) {
        if (window.size() < 2 || now - window.peekFirst()[0] < STALL_WINDOW_S) return false;
        double tolerance = Math.max(0.3, 2.5 / Math.abs(Tuned.yawTicksPerDegFront));
        double min = Double.POSITIVE_INFINITY, max = Double.NEGATIVE_INFINITY;
        for (double[] s : window) {
            min = Math.min(min, s[1]);
            max = Math.max(max, s[1]);
        }
        return max - min <= tolerance;
    }

    private double windowAverage() {
        double sum = 0;
        for (double[] s : window) sum += s[1];
        return sum / window.size();
    }
}
